250|async function initViewer(url, holder) {
251|  try {
252|    const probe = document.createElement("canvas");
253|    if (!probe.getContext("webgl")) { holder.style.display = "none"; return; }
254|    const THREE = await import("three");
255|    const orbit = await import("three/addons/controls/OrbitControls.js");
256|    const loaderMod = await import("three/addons/loaders/STLLoader.js");
257|    const w = holder.clientWidth || 400;
258|    const h = 300;
259|    const renderer = new THREE.WebGLRenderer({ antialias: true });
260|    renderer.setSize(w, h);
261|    holder.appendChild(renderer.domElement);
262|    const scene = new THREE.Scene();
263|    scene.background = new THREE.Color(0x101315);
264|    const cam = new THREE.PerspectiveCamera(45, w / h, 0.1, 10000);
265|    const ctl = new orbit.OrbitControls(cam, renderer.domElement);
266|    ctl.autoRotate = true;
267|    ctl.autoRotateSpeed = 1.0;
268|    scene.add(new THREE.HemisphereLight(0xffffff, 0x223333, 1.1));
269|    const lamp = new THREE.DirectionalLight(0xffffff, 1.4);
270|    lamp.position.set(80, 120, 60);
271|    scene.add(lamp);
272|    const geo = await new loaderMod.STLLoader().loadAsync(url);
273|    geo.computeVertexNormals();
274|    const mesh = new THREE.Mesh(
275|      geo,
276|      new THREE.MeshStandardMaterial({ color: 0xb9c2c7, metalness: 0.9, roughness: 0.35 })
277|    );
278|    scene.add(mesh);
279|    const edge = new THREE.LineSegments(
280|      new THREE.EdgesGeometry(geo, 30),
281|      new THREE.LineBasicMaterial({ color: 0x1fa39a })
282|    );
283|    mesh.add(edge);
284|    const box3 = new THREE.Box3().setFromObject(mesh);
285|    const mid = box3.getCenter(new THREE.Vector3());
286|    const size = box3.getSize(new THREE.Vector3());
287|    const far = Math.max(size.x, size.y, size.z) * 2.2;
288|    cam.position.set(mid.x + far, mid.y + far * 0.7, mid.z + far);
289|    ctl.target.copy(mid);
290|    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
291|    ctl.autoRotate = !reduced;
292|    const loop = () => {
293|      requestAnimationFrame(loop);
294|      ctl.update();
295|      renderer.render(scene, cam);
296|    };
297|    loop();
298|  } catch (err) {
299|    holder.style.display = "none";
