305|async function readStream(resp, onEvent) {
306|  const reader = resp.body.getReader();
307|  const dec = new TextDecoder();
308|  let tail = "";
309|  for (;;) {
310|    const part = await reader.read();
311|    if (part.done) break;
312|    tail += dec.decode(part.value, { stream: true });
313|    const cut = tail.split("\n\n");
314|    tail = cut.pop();
315|    for (const raw of cut) {
316|      const lines = raw.split("\n");
317|      for (const ln of lines) {
318|        const t = ln.trim();
319|        if (t.indexOf("data:") === 0) {
320|          try {
321|            onEvent(JSON.parse(t.slice(5)));
322|          } catch (err) { /* ignore */ }
323|        }
324|      }
325|    }
326|  }
